# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAKARA SURESİ 106–134. AYETLERDE MED UYGULAMALARI (KK.6.2.2)</text>\n  <rect x="18" y="46" width="212" height="196" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="124" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Medd-i Lâzım</text>\n  <text x="30" y="92" font-size="11" fill="#1e3a8a">• Sebep: Lâzım (Kalıcı) Sükûn</text>\n  <text x="30" y="110" font-size="11" fill="#1e3a8a">  (Durulsa da geçilse de var olan</text>\n  <text x="30" y="126" font-size="11" fill="#1e3a8a">  cezim veya şedde)</text>\n  <text x="30" y="150" font-size="11" font-weight="bold" fill="#1e40af">• Miktar ve Hüküm:</text>\n  <text x="30" y="168" font-size="11" fill="#1e3a8a">  4 elif miktarı uzatmak VACİPTİR.</text>\n  <text x="124" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">Örnek: الضَّآلِّينَ · آلْآنَ · الم</text>\n  <text x="124" y="222" text-anchor="middle" font-size="10.5" fill="#475569">(Şeddeli veya cezimli kalıcı sükûn)</text>\n\n  <rect x="244" y="46" width="212" height="196" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Medd-i Ârız</text>\n  <text x="256" y="92" font-size="11" fill="#14532d">• Sebep: Ârız (Geçici) Sükûn</text>\n  <text x="256" y="110" font-size="11" fill="#14532d">  (Harf-i medden sonra kelimenin</text>\n  <text x="256" y="126" font-size="11" fill="#14532d">  sonunda durulduğunda oluşur)</text>\n  <text x="256" y="150" font-size="11" font-weight="bold" fill="#166534">• Miktar ve Hüküm:</text>\n  <text x="256" y="168" font-size="11" fill="#14532d">  Tûl (4), Tevassut (2-3), Kasr (1); CAİZ.</text>\n  <text x="350" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Örnek: الْعَلِيمُ \u06dd · تَعْلَمُونَ \u06dd</text>\n  <text x="350" y="222" text-anchor="middle" font-size="10.5" fill="#475569">(Durulmayıp geçilirse Medd-i Tabiî olur)</text>\n\n  <rect x="470" y="46" width="212" height="196" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="576" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Medd-i Lîn</text>\n  <text x="482" y="92" font-size="11" fill="#713f12">• Sebep: Harf-i Lîn + Sükûn</text>\n  <text x="482" y="110" font-size="11" fill="#713f12">  (Öncesi üstünlü olan cezimli</text>\n  <text x="482" y="126" font-size="11" fill="#713f12">  وَْ veya يَْ harfinden sonra durma)</text>\n  <text x="482" y="150" font-size="11" font-weight="bold" fill="#854d0e">• Miktar ve Hüküm:</text>\n  <text x="482" y="168" font-size="11" fill="#713f12">  Yumuşakça uzatmak CAİZDİR.</text>\n  <text x="576" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Örnek: الْبَيْتِ \u06dd · خَوْفٌ \u06dd · شَيْءٍ \u06dd</text>\n  <text x="576" y="222" text-anchor="middle" font-size="10.5" fill="#475569">(Geçilirse uzatılmaz, normal okunur)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YÜZÜNDEN OKUMA İLKELERİ: MAHREÇ VE VAKIF (DURAK) İŞARETLERİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Harflerin Mahreçleri (Çıkış Yerleri)</text>\n  <text x="40" y="98" font-size="11.5" fill="#831843">• Peltek Harfler (Dil ucu): ث · ذ · ظ</text>\n  <text x="40" y="120" font-size="11.5" fill="#831843">• Boğaz Harfleri: ء · هـ · ع · ح · غ · خ</text>\n  <text x="40" y="142" font-size="11.5" fill="#831843">• Kalın (İsti\'lâ) Harfler: خ · ص · ض · غ · ط · ق · ظ</text>\n  <text x="40" y="164" font-size="11.5" fill="#831843">• Dudak Harfleri: ب · م · و · ف</text>\n  <text x="40" y="188" font-size="11" fill="#9d174d">Ayetler acele edilmeden, harflerin hakkı</text>\n  <text x="40" y="204" font-size="11" fill="#9d174d">verilerek «tertîl» üzere okunmalıdır.</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Vakıf (Durak) İşaretleri ve Uygulama</text>\n  <text x="375" y="98" font-size="11.5" fill="#581c87">• م (Vakf-ı Lâzım): Kesinlikle durulmalı.</text>\n  <text x="375" y="120" font-size="11.5" fill="#581c87">• ط (Vakf-ı Mutlak) / ج (Vakf-ı Câiz): Durulabilir.</text>\n  <text x="375" y="142" font-size="11.5" fill="#581c87">• لا (Lâ): Anlam bütünlüğü için durulmamalı.</text>\n  <text x="375" y="166" font-size="11.5" font-weight="bold" fill="#6b21a8">• Vakıfta Son Harfin Okunuşu:</text>\n  <text x="375" y="186" font-size="11" fill="#581c87">  Durulan kelimenin son harekesi (iki üstün hariç)</text>\n  <text x="375" y="204" font-size="11" fill="#581c87">  cezimliymiş gibi sakin kılınarak durulur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAKARA SURESİ 124–134: HZ. İBRAHİM\'İN KÂBE\'Yİ İNŞASI VE TÖVBE DUASI</text>\n  <rect x="25" y="48" width="650" height="94" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Kâbe\'nin (الْبَيْت) Temellerinin Yükseltilmesi ve Kabul Duası (Bakara, 2/127)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#0e7490">«İbrahim ve İsmail Kâbe\'nin temellerini yükseltirken: Rabbimiz! Bizden kabul buyur! Şüphesiz Sen Semî ve Alîm\'sin.»</text>\n\n  <rect x="25" y="152" width="650" height="90" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">2. Teslimiyet (İslam) ve Tövbe Duası (Bakara, 2/128)</text>\n  <text x="350" y="202" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِنْ ذُرِّيَّتِنَا أُمَّةً مُسْلِمَةً لَكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ</text>\n  <text x="350" y="226" text-anchor="middle" font-size="11" fill="#c2410c">«Rabbimiz! Bizi Sana teslim olanlardan kıl... Tövbemizi kabul et; şüphesiz Sen Tevvâb ve Rahîm\'sin.»</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
